    labels: [
      { id: "dnaHelix", name: "DNA Double Helix",
        shape: { type: "rect", x: 20, y: 20, w: 190, h: 340, rx: 16 },
        fill: "#E0E7FF", stroke: "#818CF8",
        description: "The twisted, ladder-like structure formed by two strands of DNA winding around each other.",
        function: "Stores the complete set of genetic instructions for building and running an organism.",
        fact: "If uncoiled, the DNA in a single human cell would stretch about 2 metres long." },
      { id: "backbone", name: "Sugar-Phosphate Backbone",
        shape: { type: "rect", x: 45, y: 35, w: 14, h: 310, rx: 7 },
        fill: "#94A3B8", stroke: "#475569",
        description: "The alternating chain of sugar and phosphate molecules that forms the outer 'rails' of each DNA strand.",
        function: "Provides the structural framework that holds the nitrogen bases in place.",
        fact: "The backbone's negative charge is what makes DNA move toward the positive electrode during gel electrophoresis." },
      { id: "bases", name: "Nitrogen Bases",
        shape: { type: "stack", cx: 125, cy: 190, rx: 55, ry: 5, count: 8, gap: 32 },
        fill: "#FCD34D", stroke: "#B45309",
        description: "The four chemical 'letters' — adenine, thymine, guanine, and cytosine — that form the rungs of the DNA ladder.",
        function: "Encode genetic information through their specific sequence along the strand.",
        fact: "The order of just four bases is enough to encode the instructions for every protein in your body." },
      { id: "basePairing", name: "Base Pairing",
        shape: { type: "rect", x: 95, y: 185, w: 60, h: 10, rx: 5 },
        fill: "#F472B6", stroke: "#BE185D",
        description: "The specific way nitrogen bases match up across the two strands: adenine with thymine, guanine with cytosine.",
        function: "Ensures each DNA strand can act as an accurate template for copying genetic information.",
        fact: "Because A always pairs with T and G always pairs with C, scientists can predict one whole strand just by reading the other." },
      { id: "hydrogenBonds", name: "Hydrogen Bonds",
        shape: { type: "circle", cx: 125, cy: 190, r: 6 },
        fill: "#FEE2E2", stroke: "#EF4444",
        description: "The weak chemical bonds that hold paired bases together across the two DNA strands.",
        function: "Allow the two strands to be held together firmly, yet still be separated when needed for copying or reading DNA.",
        fact: "A-T pairs are held by 2 hydrogen bonds, while G-C pairs are held by 3 — making G-C regions slightly more stable." },
      { id: "gene", name: "Gene",
        shape: { type: "rect", x: 30, y: 80, w: 170, h: 90, rx: 10 },
        fill: "#BEF264", stroke: "#65A30D",
        description: "A specific segment of DNA that contains the instructions for making one protein or functional product.",
        function: "Acts as the unit of hereditary information passed from parents to offspring.",
        fact: "Humans have roughly 20,000 protein-coding genes, far fewer than early estimates predicted." },
      { id: "replicationFork", name: "DNA Replication Fork",
        shape: { type: "ellipse", cx: 125, cy: 345, rx: 30, ry: 14 },
        fill: "#A5F3FC", stroke: "#0891B2",
        description: "The Y-shaped region where the DNA double helix is being unwound and separated into two single strands.",
        function: "Exposes the template strands so new complementary strands can be built during replication.",
        fact: "Replication forks in human cells move at roughly 50 nucleotides per second." },
      { id: "dnaPolymerase", name: "DNA Polymerase",
        shape: { type: "circle", cx: 175, cy: 330, r: 16 },
        fill: "#C084FC", stroke: "#7C3AED",
        description: "An enzyme that moves along an opened DNA strand during replication.",
        function: "Reads the template strand and adds matching new nucleotides to build a new complementary strand.",
        fact: "DNA polymerase can also proofread its own work, correcting most mistakes as it goes." },
      { id: "mrna", name: "mRNA",
        shape: { type: "ellipse", cx: 300, cy: 150, rx: 70, ry: 10 },
        fill: "#86EFAC", stroke: "#16A34A",
        description: "A single-stranded molecule copied from a gene's DNA sequence.",
        function: "Carries the genetic instructions from the DNA in the nucleus to the ribosome for protein synthesis.",
        fact: "mRNA uses the base uracil in place of the thymine found in DNA." },
      { id: "ribosome", name: "Ribosome",
        shape: { type: "ellipse", cx: 470, cy: 230, rx: 55, ry: 38 },
        fill: "#FDBA74", stroke: "#C2410C",
        description: "A cellular structure made of RNA and protein, either free-floating or attached to the endoplasmic reticulum.",
        function: "Reads the mRNA sequence and links amino acids together to build a protein.",
        fact: "A single ribosome can add several amino acids to a growing protein chain every second." },
      { id: "trna", name: "tRNA",
        shape: { type: "ellipse", cx: 420, cy: 170, rx: 20, ry: 14 },
        fill: "#5EEAD4", stroke: "#0D9488",
        description: "A small, folded RNA molecule that carries a specific amino acid.",
        function: "Matches its three-letter anticodon to the mRNA's codon, delivering the correct amino acid in sequence.",
        fact: "There is at least one distinct tRNA molecule for each of the 20 amino acids used to build proteins." },
      { id: "aminoAcidChain", name: "Amino Acid Chain",
        shape: { type: "stack", cx: 470, cy: 320, rx: 14, ry: 4, count: 6, gap: 11 },
        fill: "#DB2777", stroke: "#9D174D",
        description: "The growing strand of amino acids linked together as translation proceeds.",
        function: "Folds into a functional protein once translation is complete.",
        fact: "The specific sequence of amino acids determines how the finished protein folds and functions." },
    ],
