        glycolysis: { position: [-1.2, 1.8, 2.0], target: [-2.8, 0.8, 0] },
        pyruvate: { position: [0, 1.8, 2.0], target: [-1.6, 0.8, 0] },
        mitochondrion: { position: [2.4, 1.0, 1.6], target: [0.8, 0, -0.4] },
        tcaCycle: { position: [2.0, 1.5, 2.15], target: [0.4, 0.5, 0.15] },
        electronCarriers: { position: [2.5, 1.35, 2.15], target: [0.9, 0.35, 0.15] },
        electronTransportChain: { position: [2.0, 0.9, 2.15], target: [0.4, -0.1, 0.15] },
        protonGradient: { position: [2.0, 1.05, 2.2], target: [0.4, 0.05, 0.2] },
        atpSynthase: { position: [2.6, 0.9, 2.15], target: [1.0, -0.1, 0.15] },
        atp: { position: [2.9, 0.7, 2.2], target: [1.3, -0.3, 0.2] },
