  const btProteinGeo = useMemo(() => new THREE.SphereGeometry(0.09, 10, 8), []);
  const insectGeo = useMemo(() => new THREE.SphereGeometry(0.15, 12, 8), []);
  const sirnaGeo = useMemo(() => new THREE.CapsuleGeometry(0.035, 0.22, 5, 8), []);
